/// the sheet itself never opens on this path). spec-7-3's one
/// exception: an `EXPORT_EMPTY_PERIOD` create failure makes
/// `ExportJobCubit.start()` return `true` instead, so it falls through
/// to the same `ExportStatusSheet.show()` call below and opens
/// directly on "Período vazio".
Future<void> _onExportTap() async {
  if (_exportInFlight) {
    return;
  }
  _exportInFlight = true;
  try {
    final now = DateTime.now();
    final range = await showDateRangePicker(
      context: context,
      firstDate: DateTime(2000),
      lastDate: now,
      initialDateRange: DateTimeRange(
        start: now.subtract(const Duration(days: 30)),
        end: now,
      ),
    );
    if (range == null || !mounted) {
      return;
    }
    final exportCubit = sl<ExportJobCubit>();
    final started = await exportCubit.start(
      periodStart: range.start,
      periodEnd: range.end,
    );
    if (!mounted) {
      await exportCubit.close();
      return;
    }
    if (!started) {
      final message = switch (exportCubit.state) {
        ExportJobError(failure: final failure) => failure.message,
        _ => 'Não foi possível solicitar a exportação.',
      };
      await exportCubit.close();
      if (!mounted) {
        return;
      }
      ScaffoldMessenger.of(context)
          .showSnackBar(SnackBar(content: Text(message)));
      return;
    }
    await ExportStatusSheet.show(context, cubit: exportCubit);
  } finally {
    _exportInFlight = false;
  }
}

